// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title IoTDeviceRegistry - Cross-service authentication for IoT firmware updates
/// @notice Manages device registration, firmware attestation, and cross-service auth tokens
contract IoTDeviceRegistry {
    struct Device {
        bytes32 firmwareHash;
        uint256 lastAttestation;
        address owner;
        uint8 trustLevel;
    }

    struct AuthToken {
        bytes32 serviceId;
        uint256 expiry;
        bytes32 nonce;
    }

    mapping(bytes32 => Device) public devices;
    mapping(bytes32 => AuthToken[]) private pendingTokens;
    mapping(bytes32 => mapping(bytes32 => bool)) private usedNonces;
    mapping(address => bool) public trustedServices;

    address public admin;
    uint256 public constant MAX_TOKEN_LIFETIME = 3600;
    uint256 public constant ATTESTATION_INTERVAL = 86400;
    uint256 public constant MAX_PENDING_TOKENS = 10;

    event DeviceRegistered(bytes32 indexed deviceId, address owner);
    event FirmwareUpdated(bytes32 indexed deviceId, bytes32 newHash);
    event AuthTokenIssued(bytes32 indexed deviceId, bytes32 serviceId);
    event TokenConsumed(bytes32 indexed deviceId, bytes32 serviceId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyTrustedService() {
        require(trustedServices[msg.sender], "Not trusted service");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function addTrustedService(address service) external onlyAdmin {
        trustedServices[service] = true;
    }

    function registerDevice(bytes32 deviceId, bytes32 firmwareHash) external {
        require(devices[deviceId].owner == address(0), "Already registered");
        devices[deviceId] = Device({
            firmwareHash: firmwareHash,
            lastAttestation: block.timestamp,
            owner: msg.sender,
            trustLevel: 1
        });
        emit DeviceRegistered(deviceId, msg.sender);
    }

    function attestFirmware(bytes32 deviceId, bytes32 currentHash) external {
        Device storage dev = devices[deviceId];
        require(dev.owner == msg.sender, "Not device owner");
        require(dev.firmwareHash == currentHash, "Hash mismatch");
        dev.lastAttestation = block.timestamp;
        if (dev.trustLevel < 255) {
            dev.trustLevel += 1;
        }
    }

    /// @notice Issue a cross-service authentication token for a device
    /// @dev Tokens are queued and consumed by the target service
    function issueAuthToken(
        bytes32 deviceId,
        bytes32 serviceId,
        bytes32 nonce
    ) external {
        Device storage dev = devices[deviceId];
        require(dev.owner == msg.sender, "Not device owner");
        require(
            block.timestamp - dev.lastAttestation < ATTESTATION_INTERVAL,
            "Attestation expired"
        );
        require(!usedNonces[deviceId][nonce], "Nonce reused");
        require(
            pendingTokens[deviceId].length < MAX_PENDING_TOKENS,
            "Too many pending tokens"
        );

        usedNonces[deviceId][nonce] = true;

        pendingTokens[deviceId].push(AuthToken({
            serviceId: serviceId,
            expiry: block.timestamp + MAX_TOKEN_LIFETIME,
            nonce: nonce
        }));

        emit AuthTokenIssued(deviceId, serviceId);
    }

    /// @notice Consume an auth token - called by the target service
    /// @dev Searches pending tokens and validates the match
    function consumeAuthToken(
        bytes32 deviceId,
        bytes32 serviceId,
        bytes32 nonce
    ) external onlyTrustedService returns (bool) {
        AuthToken[] storage tokens = pendingTokens[deviceId];
        uint256 len = tokens.length;

        for (uint256 i = 0; i < len; i++) {
            if (tokens[i].serviceId == serviceId &&
                tokens[i].nonce == nonce &&
                tokens[i].expiry >= block.timestamp) {
                // Remove by swapping with last element
                tokens[i] = tokens[len - 1];
                tokens.pop();
                emit TokenConsumed(deviceId, serviceId);
                return true;
            }
        }
        return false;
    }

    /// @notice Batch cleanup of expired tokens for a device
    /// @dev Anyone can call this to help maintain the registry
    function cleanupExpiredTokens(bytes32 deviceId) external {
        AuthToken[] storage tokens = pendingTokens[deviceId];
        uint256 i = 0;
        while (i < tokens.length) {
            if (tokens[i].expiry < block.timestamp) {
                tokens[i] = tokens[tokens.length - 1];
                tokens.pop();
                // Note: don't increment i, check swapped element
            } else {
                i++;
            }
        }
    }

    /// @notice Verify device trust level meets minimum for a service interaction
    function verifyTrustLevel(
        bytes32 deviceId,
        uint8 minLevel
    ) external view returns (bool) {
        return devices[deviceId].trustLevel >= minLevel;
    }

    /// @notice Get count of pending tokens (for monitoring)
    function getPendingTokenCount(bytes32 deviceId) external view returns (uint256) {
        return pendingTokens[deviceId].length;
    }

    /// @notice Update firmware hash after verified OTA update
    /// @dev Attestation proof is an admin-issued signature (EIP-191) over the
    ///      update request. This binds the proof to the specific device, the
    ///      new firmware hash, and the current device state, preventing
    ///      forged/meaningless proofs from authorizing arbitrary updates.
    function updateFirmware(
        bytes32 deviceId,
        bytes32 newFirmwareHash,
        bytes calldata attestationProof
    ) external onlyTrustedService {
        Device storage dev = devices[deviceId];
        require(dev.owner != address(0), "Device not registered");

        // An ECDSA signature must be exactly 65 bytes (r=32, s=32, v=1).
        require(attestationProof.length == 65, "Invalid proof");

        // Reconstruct the message that the admin must have signed.
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                address(this),
                deviceId,
                dev.firmwareHash,
                newFirmwareHash
            )
        );
        bytes32 ethSignedHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        require(
            _recoverSigner(ethSignedHash, attestationProof) == admin,
            "Proof verification failed"
        );

        dev.firmwareHash = newFirmwareHash;
        dev.lastAttestation = block.timestamp;
        emit FirmwareUpdated(deviceId, newFirmwareHash);
    }

    function _recoverSigner(bytes32 hash, bytes calldata sig)
        internal
        pure
        returns (address)
    {
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        if (v < 27) {
            v += 27;
        }
        require(v == 27 || v == 28, "Invalid signature v");
        // Reject high-s values (malleability guard)
        require(
            uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0,
            "Invalid signature s"
        );
        address signer = ecrecover(hash, v, r, s);
        require(signer != address(0), "Invalid signature");
        return signer;
    }
}
